insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values (NULL, (select id from school_districts where slug = 'seminole-county-public-schools'), NULL, 'ambiguity', 'The policy header shows an adopted date of October 30, 2018 for every policy in the manual. Use the revised date, January 20, 2026, for the NIL policy.');
