insert into guidance_blocks (slug, block_type, scope_type, governing_body_id, applies_to, title, body, rule_topic_id, sort_order) values ('hs-step-check-brand', 'action_step', 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school', 'Check the brand against the prohibited list', 'Before you reply to an offer, make sure the product or service is not in one of the nine prohibited categories, and that the deal is not coming from a collective, a booster, a school employee or an athletic department staff member.', (select id from rule_topics where slug = 'prohibited-categories'), 10);
insert into guidance_blocks (slug, block_type, scope_type, governing_body_id, applies_to, title, body, rule_topic_id, sort_order) values ('hs-step-written', 'action_step', 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school', 'Get the deal in writing', 'An NIL agreement has to be a fully executed written contract. Make sure it ends on or before your graduation date and says exactly what you will do and what you will receive.', (select id from rule_topics where slug = 'deal-terms'), 20);
insert into guidance_blocks (slug, block_type, scope_type, governing_body_id, applies_to, title, body, rule_topic_id, sort_order) values ('hs-step-marks', 'action_step', 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school', 'Keep school marks out unless you have written consent', 'No uniform, logo, mascot or school name in the content unless your school or district has agreed in writing first. School, district, FHSAA and NFHS titles and championships cannot be mentioned in paid content at all.', (select id from rule_topics where slug = 'school-logos-marks'), 30);
insert into guidance_blocks (slug, block_type, scope_type, governing_body_id, applies_to, title, body, rule_topic_id, sort_order) values ('hs-step-parent', 'action_step', 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school', 'Review it with a parent or guardian', 'A parent or legal guardian has to sign Form GA1 with you. FHSAA also encourages families to get legal and tax advice before agreeing to a deal.', (select id from rule_topics where slug = 'parent-guardian'), 40);
insert into guidance_blocks (slug, block_type, scope_type, governing_body_id, applies_to, title, body, rule_topic_id, link_url, link_label, sort_order) values ('hs-step-ga1', 'action_step', 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school', 'File Form GA1 within five business days', 'After you sign, complete Form GA1 and hand it to your school within five business days. The school fills in its section and sends a copy to FHSAA.', (select id from rule_topics where slug = 'disclosure-required'), 'https://s3.amazonaws.com/fhsaa.org/documents/2024/10/2/GA1_Affidavit_of_Amateurism_10124.pdf', 'Form GA1 (PDF)', 50);
insert into guidance_blocks (slug, block_type, scope_type, governing_body_id, applies_to, title, body, rule_topic_id, sort_order) values ('hs-step-activities', 'action_step', 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school', 'Keep sponsors away from school time', 'Do the posts, shoots and appearances on your own time. No promoting a sponsor during any school-sponsored, district-sponsored or FHSAA activity.', (select id from rule_topics where slug = 'team-activities'), 60);
insert into guidance_blocks (slug, block_type, scope_type, governing_body_id, applies_to, title, body, rule_topic_id, sort_order) values ('hs-parent-signature', 'parent_guidance', 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school', 'Your signature is part of the process', 'A parent or legal guardian signs Form GA1 alongside the student, under penalties of perjury. Read the affidavit and the agreement before you sign.', (select id from rule_topics where slug = 'parent-guardian'), 10);
insert into guidance_blocks (slug, block_type, scope_type, governing_body_id, applies_to, title, body, rule_topic_id, sort_order) values ('hs-parent-release', 'parent_guidance', 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school', 'You release the school and FHSAA from liability', 'The bylaw says that by entering an NIL agreement, the student and parents release the school, its district or governing body, and FHSAA from liability related to the agreement.', (select id from rule_topics where slug = 'parent-guardian'), 20);
insert into guidance_blocks (slug, block_type, scope_type, governing_body_id, applies_to, title, body, rule_topic_id, sort_order) values ('hs-parent-who', 'parent_guidance', 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school', 'Know who cannot be involved', 'Coaches, school employees, athletic staff, boosters and collectives cannot arrange, offer or take part in your child''s deal. If an offer comes through one of them, treat it as a warning sign and ask the athletic director.', (select id from rule_topics where slug = 'school-staff-involvement'), 30);
insert into guidance_blocks (slug, block_type, scope_type, governing_body_id, applies_to, title, body, rule_topic_id, sort_order) values ('hs-parent-penalties', 'parent_guidance', 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school', 'Repeat violations cost eligibility', 'A first violation brings a formal warning, and the deal has to be ended or changed. A second means a year of ineligibility, and a third ends high school eligibility.', (select id from rule_topics where slug = 'penalties'), 40);
insert into guidance_blocks (slug, block_type, scope_type, applies_to, title, body, rule_topic_id, sort_order) values ('hs-parent-college', 'parent_guidance', 'level', 'high_school', 'Planning on Division I? Keep records now', 'NCAA rules require incoming Division I athletes to report third-party deals of $600 or more made since the start of junior year (or July 1, 2025, if later), within 14 days of enrolling full time or before the team''s first game, whichever comes first. Keep every contract and payment record so reporting is easy later.', (select id from rule_topics where slug = 'prospects-reporting'), 50);
insert into guidance_blocks (slug, block_type, scope_type, governing_body_id, applies_to, title, body, rule_topic_id, sort_order) values ('col-step-real-deal', 'action_step', 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college', 'Make sure it is a real deal', 'The deal should pay you for something specific you do for a business: posts, appearances, content. Money for playing, performing or choosing a school is not NIL.', (select id from rule_topics where slug = 'pay-for-play'), 10);
insert into guidance_blocks (slug, block_type, scope_type, governing_body_id, applies_to, title, body, rule_topic_id, sort_order) values ('col-step-school-rules', 'action_step', 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college', 'Check your school''s rules on logos, gear and categories', 'We found no NCAA Article 22 rule on school marks or product categories, and the NCAA tells athletes to review their campus NIL policy. Read the school rows in the matrix above and ask compliance if the deal touches logos, uniforms or facilities.', (select id from rule_topics where slug = 'school-logos-marks'), 20);
insert into guidance_blocks (slug, block_type, scope_type, state_id, applies_to, title, body, rule_topic_id, sort_order) values ('col-step-agent', 'action_step', 'state', (select id from states where code = 'FL'), 'college', 'Using an agent? Confirm the Florida license', 'Florida requires a person acting as an athlete agent on a college athlete''s NIL contracts to hold a valid Florida athlete agent license. A spouse, parent, sibling, grandparent or guardian is not treated as an athlete agent.', (select id from rule_topics where slug = 'agents'), 30);
insert into guidance_blocks (slug, block_type, scope_type, governing_body_id, applies_to, title, body, rule_topic_id, link_url, link_label, sort_order) values ('col-step-report', 'action_step', 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college', 'Report deals of $600 or more in NIL Go within five business days', 'Add up everything from the same payor, including free products and perks. You can have one representative enter the deal, but you have to submit it yourself.', (select id from rule_topics where slug = 'disclosure-required'), 'https://www.collegesportscommission.org/nil/', 'How NIL Go works', 40);
insert into guidance_blocks (slug, block_type, scope_type, governing_body_id, applies_to, title, body, rule_topic_id, sort_order) values ('col-step-wait', 'action_step', 'governing_body', (select id from governing_bodies where slug = 'college-sports-commission'), 'college', 'Watch for the review result', 'A deal comes back Cleared, Not Cleared or Flagged. If it is not cleared, you can revise and resubmit, appeal, or return the payment. Do not carry on with a deal that was not cleared.', (select id from rule_topics where slug = 'deal-review'), 50);
insert into guidance_blocks (slug, block_type, scope_type, governing_body_id, applies_to, title, body, rule_topic_id, sort_order) values ('col-parent-records', 'parent_guidance', 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college', 'A parent can enter deals, but the athlete submits', 'Each athlete may name one representative, such as a parent or agent, to enter deals in NIL Go. The athlete is still responsible for submitting them accurately and on time.', (select id from rule_topics where slug = 'disclosure-required'), 10);
insert into guidance_blocks (slug, block_type, scope_type, state_id, applies_to, title, body, rule_topic_id, sort_order) values ('col-parent-agent', 'parent_guidance', 'state', (select id from states where code = 'FL'), 'college', 'Check any agent''s Florida license', 'Florida requires a state athlete agent license to represent a college athlete on NIL contracts. Parents, guardians, siblings, grandparents and spouses are not treated as agents under the statute.', (select id from rule_topics where slug = 'agents'), 20);
insert into rule_change_log (rule_id, governing_body_id, state_id, changed_on, change_type, summary, source_id) values ((select id from rules where slug = 'fhsaa-nil-allowed'), (select id from governing_bodies where slug = 'fhsaa'), NULL, '2024-06-04', 'adopted', 'FHSAA Board of Directors approved the revision of Bylaw 9.9 to allow NIL for high school athletes.', (select id from sources where slug = 'fhsaa-letter-2024-06-21'));
insert into rule_change_log (rule_id, governing_body_id, state_id, changed_on, change_type, summary, source_id) values ((select id from rules where slug = 'fhsaa-collectives'), (select id from governing_bodies where slug = 'fhsaa'), NULL, '2024-07-22', 'amended', 'The definition of an NIL collective was revised to exclude school sanctioned team fundraising.', (select id from sources where slug = 'fhsaa-board-recap-2024-07-22'));
insert into rule_change_log (rule_id, governing_body_id, state_id, changed_on, change_type, summary, source_id) values ((select id from rules where slug = 'fhsaa-nil-allowed'), (select id from governing_bodies where slug = 'fhsaa'), NULL, '2024-07-24', 'on_agenda', 'Ratification of the NIL bylaw was on the State Board of Education agenda for approval. The vote record was not found in a primary document.', (select id from sources where slug = 'sbe-agenda-2024-07-24'));
insert into rule_change_log (rule_id, governing_body_id, state_id, changed_on, change_type, summary, source_id, previous_text, current_text) values ((select id from rules where slug = 'fhsaa-disclosure'), (select id from governing_bodies where slug = 'fhsaa'), NULL, '2024-09-25', 'amended', 'At its September 2024 meeting (recap published September 25), the FHSAA Board added a disclosure affidavit to Bylaw 9.9.', (select id from sources where slug = 'fhsaa-board-recap-2024-09'), 'Bylaw 9.9 had no affidavit requirement; section 9.9.5 held the penalties.', 'Section 9.9.5 requires Form GA1 within five business days of signing an NIL agreement; penalties moved to 9.9.6.');
insert into rule_change_log (rule_id, governing_body_id, state_id, changed_on, change_type, summary, source_id) values ((select id from rules where slug = 'fhsaa-disclosure'), (select id from governing_bodies where slug = 'fhsaa'), NULL, '2025-07-16', 'on_agenda', 'Bylaw 9.9.5 (Form GA1) was on the State Board of Education consent agenda for ratification, with the form revised 10/24 attached. The vote record was not found.', (select id from sources where slug = 'sbe-consent-2025-07-16'));
insert into rule_change_log (rule_id, governing_body_id, state_id, changed_on, change_type, summary, source_id) values ((select id from rules where slug = 'fl-college-nil-allowed'), NULL, (select id from states where code = 'FL'), '2021-07-01', 'adopted', 'Florida''s college NIL statute, section 1006.74, took effect (created by SB 646 in 2020).', (select id from sources where slug = 'fl-sb-646-2020'));
insert into rule_change_log (rule_id, governing_body_id, state_id, changed_on, change_type, summary, source_id) values ((select id from rules where slug = 'fl-college-nil-allowed'), NULL, (select id from states where code = 'FL'), '2023-02-16', 'amended', 'HB 7-B (chapter 2023-4) revised the provisions on athlete agents, athlete compensation, institutional requirements and workshops, and added a liability shield for institutions and their employees.', (select id from sources where slug = 'fl-hb-7b-2023'));
insert into rule_change_log (rule_id, governing_body_id, state_id, changed_on, change_type, summary, source_id) values ((select id from rules where slug = 'ncaa-disclosure'), (select id from governing_bodies where slug = 'ncaa'), NULL, '2025-07-01', 'adopted', 'House settlement rules took effect: direct school payments, the $600 reporting rule and NIL Go review of third-party deals.', (select id from sources where slug = 'ncaa-house-qa-2025-06'));
insert into rule_change_log (rule_id, governing_body_id, state_id, changed_on, change_type, summary, source_id, previous_text, current_text, effective_on) values ((select id from rules where slug = 'csc-deal-review'), (select id from governing_bodies where slug = 'college-sports-commission'), NULL, '2026-07-01', 'amended', 'The College Sports Commission widened the exemption from compensation-range review for deals with school-associated payors.', (select id from sources where slug = 'csc-memo-2026-06-23'), 'Deals up to $2,500 were exempt until an athlete reached $15,000 in associated deals (policy in effect from April 2026).', 'Deals of $600 to $15,000 are exempt until an athlete has more than $50,000 in associated deals in an academic year.', '2026-07-01');
insert into rule_change_log (rule_id, governing_body_id, state_id, changed_on, change_type, summary, source_id, previous_text, current_text, effective_on) values ((select id from rules where slug = 'fhsaa-nil-allowed'), (select id from governing_bodies where slug = 'fhsaa'), NULL, '2026-07-01', 'amended', 'For 2026-27 the NIL bylaw was renumbered from 9.9 to 9.10, and the NIL collectives subtitle gained the word "Defined". A word-for-word comparison with the October 2024 text found no change to what athletes may or may not do.', (select id from sources where slug = 'sbe-fhsaa-bylaws-2026-07-22'), 'Bylaw 9.9, Amateurism and Name, Image, and Likeness (NIL). Subsection 9.9.4.2, "NIL Collectives."', 'Bylaw 9.10, Amateurism and Name, Image, and Likeness (NIL). Subsection 9.10.4.2, "NIL Collectives Defined."', '2026-07-01');
insert into rule_change_log (rule_id, governing_body_id, state_id, changed_on, change_type, summary, source_id) values ((select id from rules where slug = 'fhsaa-transfers'), (select id from governing_bodies where slug = 'fhsaa'), NULL, '2026-07-22', 'on_agenda', 'Substantive amendments to Bylaw 9.3 (transfers), following SB 538, were on the State Board of Education consent agenda for ratification. The NIL transfer rule depends on the exceptions in Bylaw 9.3.2.2.', (select id from sources where slug = 'sbe-fhsaa-bylaws-2026-07-22'));
insert into rule_change_log (rule_id, governing_body_id, state_id, changed_on, change_type, summary, source_id) values ((select id from rules where slug = 'scps-nil-allowed'), NULL, NULL, '2026-10-04', 'correction', 'We located Seminole County School Board Policy 2431.06, Name, Image, and Likeness (NIL) in Athletics, revised January 20, 2026. Our earlier pages said no district NIL policy had been located.', (select id from sources where slug = 'scps-t1'));
insert into rule_change_log (rule_id, governing_body_id, state_id, changed_on, change_type, summary, source_id) values ((select id from rules where slug = 'ncaa-school-payments'), (select id from governing_bodies where slug = 'ncaa'), NULL, '2026-10-03', 'clarified', 'We added the College Sports Commission''s statement that schools outside the ACC, Big Ten, Big 12, Pac-12 and SEC choose each year whether to opt in to revenue sharing, and that NIL Go reporting applies either way.', (select id from sources where slug = 'csc-faq'));
insert into watch_items (slug, title, status_text, summary, applies_to, state_id, governing_body_id, as_of, source_id) values ('s4668-protect-college-sports-act', 'Protect College Sports Act of 2026 (S.4668)', 'Passed the Senate 77 to 22 on September 28, 2026. Not law.', 'No House action was recorded as of October 2, 2026. We have not verified the bill''s provisions, and nothing on this page changes unless it becomes law.', 'college', NULL, NULL, '2026-10-02', (select id from sources where slug = 's4668-bill-status'));
insert into watch_items (slug, title, status_text, summary, applies_to, state_id, governing_body_id, as_of, source_id) values ('fl-bog-task-force-2026', 'Florida Board of Governors task force recommendations', 'Recommendations approved September 3, 2026. Not yet law or regulation.', 'The Board approved recommendations to ask the Legislature to amend section 1006.74, to regulate agents if Congress does not act, and to require financial literacy training in an athlete''s first year.', 'college', (select id from states where code = 'FL'), (select id from governing_bodies where slug = 'florida-board-of-governors'), '2026-09-03', (select id from sources where slug = 'bog-task-force-recs-2026'));
insert into watch_items (slug, title, status_text, summary, applies_to, state_id, governing_body_id, as_of, source_id) values ('fl-hs-nil-legislation', 'Florida high school NIL legislation', 'HB 981 (2025) died in committee on June 16, 2025. We found no high school NIL statute.', 'A 2025 bill on athlete representation and compensation, which included high school NIL provisions, did not pass. FHSAA Bylaw 9.10 remains the rule we cite.', 'high_school', (select id from states where code = 'FL'), NULL, '2026-10-03', (select id from sources where slug = 'fl-hb-981-2025'));
insert into conflicts (rule_id, summary, severity, opened_on) values ((select id from rules where slug = 'uf-disclosure'), 'UF''s overview gives the NIL Go deadline two ways: "within 5 business days of signing the contract" and "within 5 days of signing". The NCAA bylaw says five business days.', 'low', '2026-10-03');
insert into conflicts (rule_id, summary, severity, opened_on) values ((select id from rules where slug = 'fhsaa-disclosure'), 'Form GA1 timing is worded three ways: the bylaw and form say within five business days of signing an NIL agreement; the State Board 2025 summary says "before participating in NIL activities"; the FHSAA September 2024 recap says within five business days "of engaging in any NIL activity". We show the bylaw and form wording.', 'medium', '2026-10-03');
insert into conflicts (rule_id, summary, severity, opened_on) values ((select id from rules where slug = 'fhsaa-school-logos-marks'), 'Bylaw 9.10.4.3 opens with an unqualified ban on school marks, then allows use with prior written consent. Form GA1 (statement 4 and Section B) treats prior written consent as the working mechanism for member school marks. We show "only with written consent".', 'low', '2026-10-03');
insert into conflicts (rule_id, summary, severity, opened_on) values ((select id from rules where slug = 'csc-deal-review'), 'The CSC memo says the exemption ends once an athlete has "exceeded" $50,000 in associated deals; the CSC NIL page says "reached". The CSC FAQ had not been updated for the new tier.', 'low', '2026-10-03');
insert into conflicts (rule_id, summary, severity, opened_on) values ((select id from rules where slug = 'uf-disclosure'), 'UF''s NIL overview names NIL Go as the reporting venue; a UF International Center FAQ says UAA policy asks athletes to report all NIL activity through a Teamworks form. The second may predate NIL Go.', 'medium', '2026-10-03');
insert into conflicts (rule_id, summary, severity, opened_on) values ((select id from rules where slug = 'fhsaa-boosters'), 'The 2026-27 Handbook renumbers the NIL bylaw to 9.10, but Bylaw 9.10.4.5 still refers to "FHSAA Bylaw 9.9", "9.9.4.2" and "9.9.4.4(i)", and Form GA1 (revised 10/24), which FHSAA still links as the current form, cites Bylaw 9.9. We read these as the same rules under their old number.', 'low', '2026-10-03');
insert into conflicts (rule_id, summary, severity, opened_on) values ((select id from rules where slug = 'fsu-agents'), 'FSU''s Compliance web page makes telling the Compliance Office a condition before an athlete first contacts an agent. FSU''s agent procedures revised February 2026 say only that it "is advised". The page shows the newer document and notes the difference.', 'medium', '2026-10-04');
